pub(crate) fn units(codepoint: u32, bold: bool, italic: bool) -> u16 {
    let face = match (bold, italic) {
        (false, false) => 0,
        (true, false) => 1,
        (false, true) => 2,
        (true, true) => 3,
    };
    let index = UNICODE_RANGES.partition_point(|(start, _, _)| *start <= codepoint);
    if index > 0 {
        let (start, end, values) = UNICODE_RANGES[index - 1];
        if codepoint >= start && codepoint <= end {
            return values[face];
        }
    }
    MISSING_UNITS[face]
}
